 1→import { getUserStagingKey, isStaging } from "../environmentVariables";
 2→
 3→/**
 4→ * getUserStagingHeader generates the correct headers for the Evergreen-Multi staging backend to correctly route requests.
 5→ * @returns - an object with a key-value pair if the headers should be applied, and an empty object if not.
 6→ */
 7→export const getUserStagingHeader = (): {
 8→  "X-Evergreen-Environment"?: string;
 9→} => {
10→  if (!isStaging()) {
11→    return {};
12→  }
13→
14→  const key = getUserStagingKey();
15→  if (!key) {
16→    return {};
17→  }
18→
19→  return { "X-Evergreen-Environment": key };
20→};
21→
22→export const shouldLogoutAndRedirect = (statusCode: number) =>
23→  statusCode === 401;
24→
25→const getErrorMessage = (response: Response, method: string) => {
26→  const { status, statusText } = response;
27→  return `${method} Error: ${status} - ${statusText}`;
28→};
29→
30→export const fetchWithRetry = <T = unknown>(
31→  url: string,
32→  options: RequestInit,
33→  retries: number = 3,
34→  backoff: number = 150,
35→): Promise<{ data: T }> =>
36→  new Promise((resolve, reject) => {
37→    const attemptFetch = (attempt: number): void => {
38→      fetch(url, options)
39→        .then((res) => {
40→          if (res.ok) {
41→            return res.json();
42→          }
43→          reject(
44→            new Error(getErrorMessage(res, "GET"), {
45→              cause: { message: res.statusText, statusCode: res.status },
46→            }),
47→          );
48→        })
49→        .then((data) => resolve(data))
50→        .catch((err) => {
51→          if (attempt <= retries) {
52→            setTimeout(() => attemptFetch(attempt + 1), backoff * attempt);
53→          } else {
54→            reject(err);
55→          }
56→        });
57→    };
58→    attemptFetch(1);
59→  });
60→

 1→const getLocalStorageString = (key: string): string | undefined => {
 2→  try {
 3→    return localStorage.getItem(key) ?? undefined;
 4→  } catch {
 5→    return undefined;
 6→  }
 7→};
 8→
 9→const setLocalStorageString = (key: string, value: string): void => {
10→  try {
11→    localStorage.setItem(key, value);
12→  } catch {
13→    // Silently fail if localStorage is unavailable or full.
14→  }
15→};
16→
17→function getLocalStorageBoolean(key: string): boolean | undefined;
18→function getLocalStorageBoolean(key: string, defaultValue: boolean): boolean;
19→
20→/**
21→ * Reads a boolean from localStorage, returning defaultValue (or undefined) if the key is absent.
22→ * @param key - The localStorage key.
23→ * @param defaultValue - Value returned when the key is absent.
24→ * @returns The stored boolean, the defaultValue, or undefined.
25→ */
26→function getLocalStorageBoolean(
27→  key: string,
28→  defaultValue?: boolean,
29→): boolean | undefined {
30→  const value = getLocalStorageString(key);
31→  if (value === undefined) return defaultValue;
32→  return value === "true";
33→}
34→
35→const setLocalStorageBoolean = (key: string, value: boolean): void => {
36→  setLocalStorageString(key, value.toString());
37→};
38→
39→export {
40→  getLocalStorageBoolean,
41→  getLocalStorageString,
42→  setLocalStorageBoolean,
43→  setLocalStorageString,
44→};
